"use client";

import { useState, type ReactNode } from "react";
import { cn } from "@/lib/utils";

const allLeadsSubs = [
  "Pipeline Overview",
  "Sales",
  "Engineering",
  "Commercial",
  "History",
] as const;

const userSubs = ["Overview", "Users", "Groups", "Policies"] as const;

const navRow =
  "flex w-full items-center gap-2.5 py-2.5 pr-3 pl-4 text-left";
const navLabel =
  "text-[14px] font-[350] leading-5 whitespace-nowrap text-[#6C7C8D]";
const subLabel =
  "text-[14px] font-[350] leading-5 whitespace-nowrap text-[rgba(29,54,80,0.65)]";
const chevron =
  "h-[16px] w-[16px] shrink-0 object-contain transition-transform duration-300 ease-[cubic-bezier(0.4,0,0.2,1)]";

function NavLabel({
  children,
  className,
  collapsed,
}: {
  children: ReactNode;
  className?: string;
  collapsed: boolean;
}) {
  return (
    <div
      className={cn(
        "min-w-0 flex-1 overflow-hidden transition-all duration-200",
        collapsed && "max-w-0 flex-none opacity-0 pointer-events-none",
      )}
    >
      <div className={cn(navLabel, className)}>{children}</div>
    </div>
  );
}

function Submenu({
  open,
  children,
}: {
  open: boolean;
  children: ReactNode;
}) {
  return (
    <div
      className={cn(
        "grid transition-[grid-template-rows] duration-300 ease-[cubic-bezier(0.4,0,0.2,1)]",
        open ? "grid-rows-[1fr]" : "grid-rows-[0fr]",
      )}
      aria-hidden={!open}
    >
      <div className="min-h-0 overflow-hidden">
        <div
          className={cn(
            "pl-6 transition-[padding,opacity] duration-300",
            open ? "py-2.5 opacity-100" : "py-0 opacity-0",
          )}
        >
          <div className="flex w-full flex-col border-l border-[rgba(13,24,61,0.15)] pl-6">
            {children}
          </div>
        </div>
      </div>
    </div>
  );
}

export function Sidebar() {
  const [collapsed, setCollapsed] = useState(false);
  const [allLeadsOpen, setAllLeadsOpen] = useState(true);
  const [userMgmtOpen, setUserMgmtOpen] = useState(true);

  const allOpen = allLeadsOpen && !collapsed;
  const userOpen = userMgmtOpen && !collapsed;

  return (
    <aside
      className={cn(
        "sticky top-0 flex h-screen min-h-screen w-60 shrink-0 flex-col items-start overflow-x-hidden overflow-y-auto border-r border-[#e6ebf1] bg-white text-[14px] text-[#6C7C8D] transition-[width,padding] duration-300 ease-[cubic-bezier(0.4,0,0.2,1)]",
        collapsed ? "w-[72px] p-3" : "w-60 p-3",
      )}
    >
      <div
        className={cn(
          "flex h-10 w-full shrink-0 items-center justify-between self-stretch box-border",
          collapsed ? "pl-0 justify-center" : "pl-5",
        )}
      >
        <div
          className={cn(
            "relative h-5 w-[51.9px] shrink-0 overflow-hidden transition-[width,opacity] duration-200",
            collapsed && "w-0 opacity-0 pointer-events-none",
          )}
        >
          <img
            className="absolute inset-0 h-full w-full object-contain object-left"
            src="/assets/images/logo.svg"
            alt="ICR"
          />
        </div>
        <button
          type="button"
          className="flex h-10 w-10 shrink-0 items-center justify-center rounded-[14px]"
          aria-label={collapsed ? "Expand sidebar" : "Collapse sidebar"}
          aria-expanded={!collapsed}
          onClick={() => setCollapsed((v) => !v)}
        >
          <img
            className={cn(
              "h-[20px] w-[20px] transition-transform duration-300",
              collapsed && "-scale-x-100",
            )}
            src="/assets/icons/sidebarHumberger.svg"
            alt="sidebar hamburger icon"
          />
        </button>
      </div>

      <div
        className={cn(
          "flex w-full flex-col items-start self-stretch",
          collapsed ? "px-0 py-4" : "pt-4 pr-3 pb-4 pl-4",
        )}
      >
        <button
          type="button"
          className={cn(
            "flex w-full items-center justify-center gap-1 overflow-hidden rounded-[10px] bg-[#f6861f]",
            collapsed ? "p-2.5" : "px-4 py-2.5",
          )}
        >
          <img className="h-[16px] w-[16px] shrink-0" src="/assets/icons/newLead.svg" alt="" />
          <span
            className={cn(
              "text-[12px] font-[350] leading-[145%] tracking-[-0.48px] text-white whitespace-nowrap transition-[opacity,width] duration-200",
              collapsed && "w-0 overflow-hidden opacity-0",
            )}
          >
            New Lead
          </span>
        </button>
      </div>

      <nav className="flex w-full flex-col items-stretch self-stretch">
        <div className="flex w-full flex-col self-stretch">
          <button
            type="button"
            className={cn(
              navRow,
              "rounded-[10px]",
              collapsed && "justify-center gap-0 px-2.5",
            )}
            aria-expanded={allOpen}
            onClick={() => {
              if (collapsed) {
                setCollapsed(false);
                setAllLeadsOpen(true);
                return;
              }
              setAllLeadsOpen((v) => !v);
            }}
          >
            <img
              className="h-[20px] w-[20px] shrink-0 self-center"
              src="/assets/icons/SidebarLeeds.svg"
              alt="all leads icon"
            />
            <NavLabel collapsed={collapsed}>All Leads</NavLabel>
            <img
              className={cn(
                chevron,
                allOpen ? "rotate-0" : "rotate-180",
                collapsed && "w-0 overflow-hidden opacity-0",
              )}
              src="/assets/icons/chevronUp.svg"
              alt="chevron up icon"
            />
          </button>
          <Submenu open={allOpen}>
            {allLeadsSubs.map((item, index) => (
              <a
                key={item}
                href="#"
                className={cn(
                  "box-border flex h-10 w-[165px] flex-col items-start justify-center px-3 py-2.5",
                  index === 0 && "rounded-lg",
                )}
              >
                <div className={index === 0 ? navLabel : subLabel}>{item}</div>
              </a>
            ))}
          </Submenu>
        </div>

        <a
          href="#"
          className={cn(
            navRow,
            "rounded-r-md text-[#f6861f]",
            collapsed && "justify-center gap-0 px-2.5",
          )}
        >
          <img
            className="h-[20px] w-[20px] shrink-0"
            src="/assets/icons/dashboardIcon.svg"
            alt="dashboard icon"
          />
          <NavLabel collapsed={collapsed} className="text-[#f6861f]">
            Dashboard
          </NavLabel>
        </a>

        <a
          href="#"
          className={cn(
            navRow,
            "rounded-r-md",
            collapsed && "justify-center gap-0 px-2.5",
          )}
        >
          <img
            className="h-[20px] w-[20px] shrink-0"
            src="/assets/icons/customers.svg"
            alt="customers icon"
          />
          <NavLabel collapsed={collapsed} className="text-[rgba(29,54,80,0.65)]">
            Customers
          </NavLabel>
        </a>

        <div className="flex w-full flex-col self-stretch">
          <button
            type="button"
            className={cn(
              navRow,
              "rounded-[10px]",
              collapsed && "justify-center gap-0 px-2.5",
            )}
            aria-expanded={userOpen}
            onClick={() => {
              if (collapsed) {
                setCollapsed(false);
                setUserMgmtOpen(true);
                return;
              }
              setUserMgmtOpen((v) => !v);
            }}
          >
            <img
              className="h-[20px] w-[20px] shrink-0"
              src="/assets/icons/userManagement.svg"
              alt="user management icon"
            />
            <NavLabel collapsed={collapsed}>User Management</NavLabel>
            <img
              className={cn(
                chevron,
                userOpen ? "rotate-0" : "rotate-180",
                collapsed && "w-0 overflow-hidden opacity-0",
              )}
              src="/assets/icons/chevronUp.svg"
              alt="chevron up icon"
            />
          </button>
          <Submenu open={userOpen}>
            {userSubs.map((item, index) => (
              <a
                key={item}
                href="#"
                className={cn(
                  "box-border flex w-full flex-col items-start justify-center px-3",
                  index === 0
                    ? "pb-2.5 pt-0"
                    : index === userSubs.length - 1
                      ? "pb-0 pt-2.5"
                      : "h-10 py-2.5",
                )}
              >
                <div className={subLabel}>{item}</div>
              </a>
            ))}
          </Submenu>
        </div>

        <a
          href="#"
          className={cn(
            navRow,
            "rounded-r-md",
            collapsed && "justify-center gap-0 px-2.5",
          )}
        >
          <span className="inline-flex h-[20px] w-[20px] shrink-0 items-center justify-center">
            <img className="h-[16px] w-[16px]" src="/assets/icons/support.svg" alt="" />
          </span>
          <NavLabel collapsed={collapsed} className="text-[rgba(29,54,80,0.65)]">
            Support
          </NavLabel>
        </a>
      </nav>
    </aside>
  );
}
